module probe;
import bootstrap::model;
import bootstrap::ir;
fn same(i:model::Inst,j:model::Inst)->bool { return i.op==j.op && i.dst==j.dst && i.a==j.a && i.b==j.b && i.c==j.c && i.aux==j.aux && i.bits==j.bits && i.span.file==j.span.file && i.span.start==j.span.start && i.span.end==j.span.end; }
pub fn run()->u32 {
 model::reset_all(); ir::reset();
 unsafe { ir::location=model::Span {file:3,start:17,end:29}; }
 let a:u32=ir::slot(model::TYPE_USIZE); let b:u32=ir::slot(model::TYPE_USIZE);
 ir::copy_to(a,b); ir::emit(model::IR_COPY,a,b,0,0,0,0);
 ir::bounds(a,b); ir::emit(model::IR_BOUNDS,0,a,b,0,0,0);
 ir::call(a,43,51,6); ir::emit(model::IR_CALL,a,43,51,6,0,0);
 ir::return_value(a); ir::emit(model::IR_RETURN,0,a,0,0,0,0);
 ir::panic_(); ir::emit(model::IR_PANIC,0,0,0,0,0,0);
 unsafe {
  var i:u32=1; while i<=10_u32 { if !same(model::insts[i as usize],model::insts[(i+1_u32) as usize]) {return i;} i=i+2_u32; }
  if !ir::closed {return 12;}
 }
 let result:u32=ir::unary(model::UNARY_BIT_NOT,a,model::TYPE_USIZE);
 unsafe {
  if result!=3_u32 || model::slot_count!=3_u32 || model::inst_count!=11_u32 {return 13;}
  let instruction:model::Inst=model::insts[11];
  if instruction.op!=model::IR_UNARY || instruction.dst!=result || instruction.a!=a || instruction.b!=0_u32 || instruction.c!=0_u32 || instruction.aux!=model::UNARY_BIT_NOT || instruction.bits!=0_usize {return 14;}
  if model::slots[result as usize].ty!=model::TYPE_USIZE || model::slots[result as usize].span.start!=17_u32 || instruction.span.end!=29_u32 {return 15;}
 }
 return 0;
}

